    private const string EmptyResult = @"<soap:Envelope xmlns:soap=""http://schemas.xmlsoap.org/soap/envelope/""><soap:Body><ns2:queryUsersResponse xmlns:ns2=""http://adnovum.ch/nevisidm/ws/services/v1""/></soap:Body></soap:Envelope>";

    [Test]
    public async Task SearchUsersByQuery_WhenNoResults_ReturnsEmptyList()
    {
        //Arrange
        var httpClientFactoryMock = Substitute.For<IHttpClientFactory>();
        var mockHttpClient = new HttpClient(new MockHttpMessageHandler(EmptyResult)) { BaseAddress = new Uri("https://unittest.com") };
        httpClientFactoryMock.CreateClient(Arg.Any<string>()).Returns(mockHttpClient);

        var eiamSoapApiClient = new EIAMSoapApiClient(httpClientFactoryMock);

        //Act
        var results = await eiamSoapApiClient.SearchUsersByQuery("NonExistentUser");

        //Assert
        results.Should().NotBeNull();
        results.Should().BeEmpty();
    }

    [Test]
    public async Task SearchUsersByQuery_WhenResults_ReturnsDistinctUsers()
    {
        //Arrange
        var httpClientFactoryMock = Substitute.For<IHttpClientFactory>();
        var mockHttpClient = new HttpClient(new MockHttpMessageHandler(ValidResult)) { BaseAddress = new Uri("https://unittest.com") };
        httpClientFactoryMock.CreateClient(Arg.Any<string>()).Returns(mockHttpClient);

        var eiamSoapApiClient = new EIAMSoapApiClient(httpClientFactoryMock);

        //Act
        var results = await eiamSoapApiClient.SearchUsersByQuery("ExistingUser");

        // Assert
        results.Should().NotBeNull();
        results.Should().NotBeEmpty();
    }
}

public class MockHttpMessageHandler : HttpMessageHandler
{
    private readonly string _response;
    private readonly HttpStatusCode _statusCode;

    public string? Input { get; private set; }
    public int NumberOfCalls { get; private set; }

    public MockHttpMessageHandler(string response, HttpStatusCode statusCode = HttpStatusCode.OK)
    {
        _response = response;
        _statusCode = statusCode;
    }

    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,
        CancellationToken cancellationToken)
    {
        NumberOfCalls++;
        
        if (request.Content != null) // Could be a GET-request without a body
        {
            Input = await request.Content.ReadAsStringAsync();
        }

        return new HttpResponseMessage
        {
            StatusCode = _statusCode,
            Content = new StringContent(_response)
        };
    }
}
